using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Threading;using System.Web.Script.Serialization;using System.Windows.Forms;using System.Drawing;using System.Runtime.InteropServices;using System.Text.RegularExpressions;
public static class GuntConfiguration {
 public static Dictionary<string,object> Read(string root,string name){string p=Path.Combine(root,"config",name+".json");for(int i=0;;i++){try{return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(p,Encoding.UTF8));}catch(IOException){if(i==3)throw;Thread.Sleep(30);}}}
 public static int Number(Dictionary<string,object> d,string k,int v){return d.ContainsKey(k)&&d[k]!=null?Convert.ToInt32(d[k]):v;}
 public static bool Flag(Dictionary<string,object> d,string k,bool v){return d.ContainsKey(k)&&d[k]!=null?Convert.ToBoolean(d[k]):v;}
 public static string Text(Dictionary<string,object> d,string k,string v){return d.ContainsKey(k)&&d[k]!=null?Convert.ToString(d[k]):v;}
 static void Range(Dictionary<string,object> d,string key,int min,int max){if(d.ContainsKey(key)){int n=Convert.ToInt32(d[key]);if(n<min||n>max)throw new ArgumentException(key+" 값은 "+min+"–"+max+" 범위여야 합니다.");}}
 public static void Validate(string name,Dictionary<string,object> d){
  if(name=="theme"){var palette=d.ContainsKey("palette")?d["palette"] as Dictionary<string,object>:null;if(palette!=null)foreach(var color in palette.Values)if(!Regex.IsMatch(Convert.ToString(color),@"^#[0-9A-Fa-f]{6}$"))throw new ArgumentException("색상은 #RRGGBB 형식으로 입력하세요.");}
  if(name=="startup"){Range(d,"delaySeconds",0,10);Range(d,"retryCount",0,2);Range(d,"retryDelaySeconds",0,5);}
  if(name=="sensors"){Range(d,"staleSeconds",5,60);if(Text(d,"provider","auto")!="auto"&&Text(d,"provider","auto")!="none")throw new ArgumentException("지원하는 온도 공급자를 선택하세요.");}
  if(name=="monitor"){Range(d,"width",300,520);Range(d,"radius",0,20);Range(d,"margin",0,200);Range(d,"topGap",0,200);Range(d,"networkFixedMaxBytesPerSecond",1024,Int32.MaxValue);int interval=Number(d,"updateMs",2000),history=Number(d,"graphHistorySeconds",60);if(interval!=1000&&interval!=2000&&interval!=5000)throw new ArgumentException("갱신 간격은 1000·2000·5000ms 중 선택하세요.");if(history!=30&&history!=60&&history!=120)throw new ArgumentException("그래프 이력은 30·60·120초 중 선택하세요.");if(Text(d,"networkScaleMode","dynamic")!="dynamic"&&Text(d,"networkScaleMode","dynamic")!="fixed")throw new ArgumentException("네트워크 축 설정을 확인하세요.");}
  if(name=="topbar"){Range(d,"height",36,52);Range(d,"fontSize",12,18);Range(d,"iconSize",17,24);Range(d,"brandSize",16,24);if(Text(d,"brandText","").Length>80)throw new ArgumentException("브랜드 문구가 너무 깁니다.");}
 }
 public static string Save(string root,string name,Dictionary<string,object> d){if(!Regex.IsMatch(name,@"^[a-zA-Z0-9-]+$"))throw new ArgumentException("설정 이름이 올바르지 않습니다.");Validate(name,d);string path=Path.Combine(root,"config",name+".json");return Atomic(root,path,new JavaScriptSerializer().Serialize(d),true);}
 public static string Atomic(string root,string path,string content,bool backup){bool held=false;using(var mutex=new Mutex(false,"Local\\GUNTSettingsV24")){try{held=mutex.WaitOne(15000);if(!held)throw new IOException("다른 설정 적용을 기다리는 중입니다.");Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp",revision=null;try{File.WriteAllText(temp,content,new UTF8Encoding(false));if(File.Exists(path)){if(backup){revision=Path.Combine(root,"backups","settings-v24",DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+"-"+Guid.NewGuid().ToString("N").Substring(0,6),Path.GetFileName(path));Directory.CreateDirectory(Path.GetDirectoryName(revision));}File.Replace(temp,path,revision);}else File.Move(temp,path);return revision;}finally{if(File.Exists(temp))File.Delete(temp);}}finally{if(held)mutex.ReleaseMutex();}}}
}
public static class GuntLayout {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct DISPLAY_DEVICE{public int cb;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)]public string DeviceName;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string DeviceString;public int Flags;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string DeviceID;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string DeviceKey;}
 [StructLayout(LayoutKind.Sequential)]public struct RECT{public int Left,Top,Right,Bottom;}
 public delegate bool EnumCallback(IntPtr h,IntPtr p);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool EnumDisplayDevices(string name,uint index,ref DISPLAY_DEVICE info,uint flags);
 [DllImport("user32.dll")]static extern IntPtr MonitorFromPoint(Point p,uint flags);
 [DllImport("shcore.dll")]static extern int GetDpiForMonitor(IntPtr h,int type,out uint x,out uint y);
 [DllImport("user32.dll")]public static extern bool GetWindowRect(IntPtr h,out RECT r);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumCallback c,IntPtr p);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder t,int n);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr h,StringBuilder t,int n);
 public static string MonitorId(Screen screen){var d=new DISPLAY_DEVICE();d.cb=Marshal.SizeOf(typeof(DISPLAY_DEVICE));return EnumDisplayDevices(screen.DeviceName,0,ref d,1)&&!String.IsNullOrEmpty(d.DeviceID)?d.DeviceID:screen.DeviceName;}
 public static double Scale(Screen screen){uint x=96,y=96;GetDpiForMonitor(MonitorFromPoint(new Point(screen.Bounds.Left+1,screen.Bounds.Top+1),2),0,out x,out y);return x/96.0;}
 public static IntPtr MonitorWindow(){IntPtr result=IntPtr.Zero;EnumWindows(delegate(IntPtr h,IntPtr p){var t=new StringBuilder(512);var c=new StringBuilder(128);GetWindowText(h,t,512);GetClassName(h,c,128);if(c.ToString()=="RainmeterMeterWindow"&&t.ToString().Contains("GUNT-System-Monitor"))result=h;return true;},IntPtr.Zero);return result;}
 public static Dictionary<string,object> Resolve(string root,int heightDip){var m=GuntConfiguration.Read(root,"monitor");Dictionary<string,object> position=null;if(m.ContainsKey("position"))position=m["position"] as Dictionary<string,object>;bool manual=position!=null&&GuntConfiguration.Text(position,"mode","auto")=="manual";Screen screen=Screen.PrimaryScreen;bool found=false;if(manual){foreach(var s in Screen.AllScreens)if(MonitorId(s)==GuntConfiguration.Text(position,"monitorId","")){screen=s;found=true;break;}}
  double scale=Scale(screen);var work=screen.WorkingArea;int width=(int)Math.Round(GuntConfiguration.Number(m,"width",360)*scale);int height=(int)Math.Round(heightDip*scale);int x=work.Right-width-(int)Math.Round(GuntConfiguration.Number(m,"margin",24)*scale),y=work.Top+(int)Math.Round(GuntConfiguration.Number(m,"topGap",20)*scale);
  if(manual&&found){x=work.Left+(int)Math.Round(Convert.ToDouble(position["xDip"])*scale);y=work.Top+(int)Math.Round(Convert.ToDouble(position["yDip"])*scale);}
  x=Math.Max(work.Left+8,Math.Min(x,work.Right-width-8));y=Math.Max(work.Top+8,Math.Min(y,work.Bottom-height-8));return new Dictionary<string,object>{{"x",x},{"y",y},{"scale",scale},{"monitorId",MonitorId(screen)},{"device",screen.DeviceName},{"temporaryFallback",manual&&!found},{"workHeight",work.Height},{"workWidth",work.Width}};
 }
 public static void SavePosition(string root,IntPtr h){RECT r;if(!GetWindowRect(h,out r))return;var screen=Screen.FromRectangle(new Rectangle(r.Left,r.Top,r.Right-r.Left,r.Bottom-r.Top));double scale=Scale(screen);var m=GuntConfiguration.Read(root,"monitor");var old=m.ContainsKey("position")?m["position"] as Dictionary<string,object>:null;if(old!=null&&GuntConfiguration.Flag(old,"locked",false))return;m["position"]=new Dictionary<string,object>{{"mode","manual"},{"locked",false},{"monitorId",MonitorId(screen)},{"xDip",Math.Round((r.Left-screen.WorkingArea.Left)/scale,2)},{"yDip",Math.Round((r.Top-screen.WorkingArea.Top)/scale,2)}};GuntConfiguration.Save(root,"monitor",m);}
}
